    await service.BuscarAsync(id, ct) is { } p ? Results.Ok(p) : Results.NotFound());
produtos.MapPost("/", async (NovoProduto dto, IProdutoService service, CancellationToken ct) =>
{
    var criado = await service.CriarAsync(dto, ct);
    return Results.Created($"/produtos/{criado.Id}", criado);
