public class Pedido
{
    public int Id { get; set; }
    public required string ClienteEmail { get; set; }
    public List<ItemPedido> Itens { get; set; } = [];
}

public class LojaContext(DbContextOptions<LojaContext> options) : DbContext(options)
{
    public DbSet<Pedido> Pedidos => Set<Pedido>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Pedido>().HasMany(p => p.Itens).WithOne().OnDelete(DeleteBehavior.Cascade);
        model.Entity<Pedido>().HasIndex(p => p.ClienteEmail);
    }
}

public class ProdutosApiTests(WebApplicationFactory<Program> factory)
    : IClassFixture<WebApplicationFactory<Program>>
{
    [Fact]
    public async Task Post_sem_nome_devolve_400()
    {
        var client = factory.CreateClient();

        var resposta = await client.PostAsJsonAsync("/produtos", new { preco = 10 });

        Assert.Equal(HttpStatusCode.BadRequest, resposta.StatusCode);
        var problema = await resposta.Content.ReadFromJsonAsync<ValidationProblemDetails>();
        Assert.Contains("Nome", problema!.Errors.Keys);
    }
}

